src=(R/'css/style.css').read_text(); block=src[src.index(':root {'):src.index('}',src.index(':root {'))]
tokens={k:re.search(r'--'+k+r':\s*([^;]+)',block).group(1) for k in ['text','paper','cyan','cyan2','gold','green','red','purple']}
(P/'assets/provenance.json').write_text(json.dumps({'sourceCommit':'35bcb63c0c9682bb9d32885063c8b7dc7b3c86df','assets':['icons/launch/valley-landscape.jpg','fonts/Fredoka-latin-500.woff2'],'paletteSource':'css/style.css :root','tokens':tokens,'purpose':'Review concept, no runtime game changes'},indent=2)+'\n')
def card(title,body,tag=''):
 return f'<article class="card"><div class="row"><h2>{title}</h2>{("<span class=tag>"+tag+"</span>") if tag else ""}</div>{body}</article>'
def rows(items):
 return ''.join('<div class="item"><div><b>'+a+'</b><p>'+b+'</p></div><span class="state">'+c+'</span></div>' for a,b,c in items)
def chart(title,values,label,labels=None):
 bars=''.join(f'<div class="barcol"><div class="bar" style="height:{round(v/max(values)*95)}px"></div><small>{html.escape(labels[i]) if labels else i+1}</small></div>' for i,v in enumerate(values))
 return card(title,f'<p class="muted">{label} · fictional example</p><div class="chart" role="img" aria-label="Fictional example values: {", ".join(map(str,values))}">{bars}</div><details><summary>What this means & source values</summary><p>Illustration only. Values: {", ".join(map(str,values))}. Production needs an eligible population, time basis, freshness and source-backed denominator.</p></details>')
pages={}
pages['home']=('<span class="eyebrow">YOUR VALLEY AT A GLANCE</span><h1>Your valley, at a glance.</h1><p>Review what matters. Open any detail.</p>',
 card('Needs your attention',rows([('Review the next release','Open the evidence and unresolved gaps.','Review'),('Check reporting coverage','One source has no current observation.','Unknown')]),'2 examples')+
 '<div class="metrics"><article><small>Reporting installs</small><strong>42</strong><span>Example · last 7 days</span></article><article><small>Content readiness</small><strong>Not audited</strong><span>Inventory required</span></article><article><small>Reported play</small><strong>18.4 h</strong><span>Example · not screen time</span></article><article><small>Recorded costs</small><strong>A$120</strong><span>Example · month to date</span></article></div>'+
 chart('Reporting activity',[32,48,38,65,58,79,85],'Reporting installations by day')+
 card('Game → website → Studio', '<p>One item. Its player experience, website explanation, controls and evidence together.</p><a class="action" href="#game">Explore the item workspace</a>')+
 card('What is actually confirmed?',rows([('Content & controls','Fresh inventory and capability audit needed.','Pending'),('Configuration delivery','Received revision differs from proven effect.','Explain'),('Source health','Show unavailable and stale separately.','View')])) )
pages['people']=('<span class="eyebrow">PEOPLE & DEVICES</span><h1>Understand the family experience.</h1><p>Names stay with their reporting installation. No guessed identity joins.</p>',
 card('Find a reported profile','<label>Child or device <input placeholder="Search example records" aria-label="Search fictional profiles"></label><p class="muted">Illustrative records only. Actual access requires private-detail permission.</p>')+
 card('Linh · example profile',rows([('Family tablet','Installation demo-tablet · v1.02','Tablet'),('Reported play','Illustrative active minutes in this period.','84 min'),('Last report','Example observation, not live presence.','Example')]),'Fictional')+
 chart('Reported play',[18,30,12,37,21,28,34],'Active minutes on this installation')+
 card('Connected evidence',rows([('Activities','What was reported, with compatible detail.','Open'),('Problems','Original evidence, subject to report access.','Open'),('Configuration','Exact revision/hash receipt; offline is pending.','Open')]))+
 card('Privacy is part of the design','<p>Parent Analytics off takes precedence. Family access, management access and marketing reporting have separate boundaries.</p>'))
pages['game']=('<span class="eyebrow">GAME & WEBSITE</span><h1>Every experience.<br>One connected workspace.</h1><p>Games, stories, quests, festivals and the world—not just a catalogue.</p>',
 card('Complete coverage', '<div class="chips">'+''.join('<span>'+x+'</span>' for x in ['Games','Stories','Quests','Rewards','Festivals','World','Multiplayer','Voice & media','Website'])+'</div><p class="muted">Full 13-domain management scope is documented. This is not an audited runtime inventory.</p>')+
 card('Reading activity · example',rows([('Source & player entry','Stable kind:id, implementation and dependencies.','Audit'),('Game availability','Show real capability and effective rule.','Explain'),('Website guide','Same reviewed build, artwork and facts.','Review'),('Usage & experience','Starts, outcomes, repeat play and errors.','Evidence')]),'Item workspace')+
 card('A control you can understand','<h3>Availability</h3><p>Purpose: show or hide this supported activity. Explain affected surfaces and safe apply timing before publishing.</p><div class="flow">Private draft → Review → Publish → Readback</div><p class="muted">A real private draft backend is still required. Current configuration POST publishes.</p><button disabled>Concept only · no publish action</button>')+
 card('Do not confuse these states','<p>Listed → implemented → playable → controllable → measured → explained. Each requires its own evidence.</p>'))
pages['marketing']=('<span class="eyebrow">WITHIN GAME & WEBSITE</span><h1>Growth you can explain.</h1><p>See what brings families in and what makes them return.</p>',
 card('Acquisition to meaningful play','<div class="funnel"><div>Campaign / referral <b>Example source</b></div><div>Website visit <b>Observable events</b></div><div>Download / launch click <b>Not an install</b></div><div>First activity <b>Join not established</b></div><div>Return play <b>Cohort contract needed</b></div></div><p class="muted">Proposed journey. Unknown attribution remains unknown.</p>')+
 chart('Landing-page actions',[65,40,81,55,72],'Illustrative aggregate actions, not unique people')+
 card('Decisions this should support',rows([('Acquisition','Which channels justify recorded spend?','Compare'),('Activation','Where do first-time installations stop?','Inspect'),('Retention','Which activities bring return play?','Cohorts'),('Experiments','Hypothesis, sample, result and decision.','Review')]))+
 card('Family privacy','<p>Marketing uses eligible aggregate or pseudonymous measures. Child names are not advertising identities or marketing audience keys.</p>'))
pages['work']=('<span class="eyebrow">WORK, RELEASES & SERVICES</span><h1>From a problem<br>to proven progress.</h1><p>Original evidence, clear ownership and understandable release gates.</p>',
 card('Review queue',rows([('Reported problem','Original report plus authorised follow-up.','Triage'),('Website alignment','Check explanations against exact game source.','Review'),('Release evidence','Tests, limitations and owner decision.','Inspect')]))+
 card('Change delivery','<div class="steps">'+''.join('<p><b>'+str(i+1)+'</b> '+s+'</p>' for i,s in enumerate(['Prepare a real private draft','Review scope, permission and consequences','Publish supported config or reviewed build','Read back the public revision','Observe matching device receipts']))+'</div><p class="muted">Saved, published, deployed and received are different facts.</p>')+
 card('Services & resource use',rows([('Netlify Database','Existing service selected; live binding must be verified.','Pending'),('Provider observations','Missing credentials are not healthy service evidence.','Unknown'),('Reporting budgets','Track requests, bytes and database growth.','Proposed')]))+
 card('Release authority','<p>No main merge, deployment or version bump without the required owner approval. A green test run does not approve a release.</p>'))
pages['money']=('<span class="eyebrow">MONEY</span><h1>Know the recorded cost.</h1><p>Clear coverage, exact values and a traceable history.</p>',
 '<div class="metrics"><article><small>Recorded cost</small><strong>A$120</strong><span>Fictional month example</span></article><article><small>Budget</small><strong>A$200</strong><span>Fictional month example</span></article></div>'+
 chart('Budget & recorded cost',[200,120],'AUD · budget versus recorded cost',['Budget','Cost'])+
 card('Understand the basis',rows([('Period & currency','Explicit month, AUD and invoice/cash basis.','Visible'),('Coverage','Missing invoices/FX stay unavailable.','Partial'),('History','Preview, commit, correction and audit.','Traceable')]))+
 card('Costs that connect','<p>Link recorded hosting, database, media and campaign costs to their evidence. Provider billing feeds need real verified access.</p>')+
 card('Scope','<p>This is a manual-first management ledger. No bank payments, complete company profit or statutory-accounting completeness is implied.</p>'))
pages['settings']=('<span class="eyebrow">SETTINGS · PROPOSED PANEL</span><h1>Full capability.<br>Controlled overhead.</h1><p>Optional functions have independent controls and clear consequences.</p>',
 card('Resource mode','<label>Illustrative preset <select id="preset"><option>Essential</option><option>Standard</option><option>Detailed temporarily</option><option>Custom</option></select></label><p class="muted">Preset membership and numeric budgets require implementation and measurement.</p>')+
 card('Optional engagement reporting',''.join('<div class="switchrow"><div><b>'+a+'</b><p>'+b+'</p></div><button class="toggle" role="switch" aria-checked="false">Off</button></div>' for a,b in [('Collect','Game/website measurements'),('Process','Optional server aggregation'),('Show','Studio dashboard visibility')])+'<p class="muted">Interactive illustration only. These switches change no real policy.</p>')+
 card('Delivery & protection',rows([('Parent choice','Analytics off overrides Studio enabling.','Priority'),('Offline devices','Changes wait until received or policy expires.','Pending'),('Gameplay & saves','Optional reporting never blocks or rewrites them.','Protect'),('Diagnostics','Bounded sampling with automatic expiry.','Required')]))+
 card('What Off means','<p>Hide is not stop collecting. Stop processing is not delete data. Disable actual producers, timers and optional uploads; verify measured effects.</p>'))
